import React from 'react';
import { MoreVertical } from 'lucide-react';

const DashboardCards = () => {
  const cards = [
    {
      title: 'Summary',
      number: '21',
      label: 'Due Tasks',
      color: 'blue',
      subtext: 'Completed: 13'
    },
    {
      title: 'Overdue',
      number: '17',
      label: 'Tasks',
      color: 'red',
      subtext: 'From yesterday: 9'
    },
    {
      title: 'Issues',
      number: '24',
      label: 'Open',
      color: 'orange',
      subtext: 'Closed today: 19'
    },
    {
      title: 'Features',
      number: '38',
      label: 'Proposals',
      color: 'green',
      subtext: 'Implemented: 16'
    }
  ];

  return (
    <div className="dashboard-cards">
      {cards.map((card, index) => (
        <div key={index} className="dashboard-card">
          <div className="card-header">
            <h3 className="card-title">{card.title}</h3>
            <MoreVertical className="card-menu" />
          </div>
          <div className="card-content">
            <div className={`card-number ${card.color}`}>{card.number}</div>
            <div className={`card-label ${card.color}`}>{card.label}</div>
            <div className="card-subtext">{card.subtext}</div>
          </div>
        </div>
      ))}
    </div>
  );
};

export default DashboardCards;
